import React, { useRef } from 'react';
import { confirmDialog } from 'primereact/confirmdialog';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';

export default function Position() {
    const toast = useRef(null);

    const accept = () => {
        toast.current.show({ className: 'info', summary: 'Confirmed', detail: 'You have accepted', life: 3000 });
    }

    const reject = () => {
        toast.current.show({ className: 'warn', summary: 'Rejected', detail: 'You have rejected', life: 3000 });
    }

    const confirm3 = (position) => {
        confirmDialog({
            message: 'Do you want to delete this record?',
            header: 'Delete Confirmation',
            icon: 'pi pi-info-circle',
            acceptClassName: 'danger',
            rejectClassName: 'text',
            position,
            accept,
            reject
        });
    };

    return (
        <>
            <Toast ref={toast} />
            <div className="fxb fvc gp5 mgb5">
                <Button label="Left" icon="pi pi-arrow-right" onClick={() => confirm3('left')} className="help" style={{ minWidth: '10rem' }} />
                <Button label="Right" icon="pi pi-arrow-left" onClick={() => confirm3('right')} className="help" style={{ minWidth: '10rem' }} />
            </div>
            <div className="fxb fvc gp5 mgb5">
                <Button label="TopLeft" icon="pi pi-arrow-down-right" onClick={() => confirm3('top-left')} className="warning" style={{ minWidth: '10rem' }} />
                <Button label="Top" icon="pi pi-arrow-down" onClick={() => confirm3('top')} className="warning" style={{ minWidth: '10rem' }} />
                <Button label="TopRight" icon="pi pi-arrow-down-left" onClick={() => confirm3('top-right')} className="warning" style={{ minWidth: '10rem' }} />
            </div>
            <div className="fxb fvc gp5">
                <Button label="BottomLeft" icon="pi pi-arrow-up-right" onClick={() => confirm3('bottom-left')} className="success" style={{ minWidth: '10rem' }} />
                <Button label="Bottom" icon="pi pi-arrow-up" onClick={() => confirm3('bottom')} className="success" style={{ minWidth: '10rem' }} />
                <Button label="BottomRight" icon="pi pi-arrow-up-left" onClick={() => confirm3('bottom-right')} className="success" style={{ minWidth: '10rem' }} />
            </div>
        </>
    )

}